<template><Popover v-model:open="open"><PopoverTrigger as-child><button class="chat-tools-trigger" :disabled="disabled" aria-label="Choose connected tools"><Wrench :size="15" /><span>Tools{{ tools.length ? ` · ${selected.length}` : '' }}</span></button></PopoverTrigger><PopoverContent align="end" side="top" :collision-padding="12" :side-offset="8" :avoid-collisions="true" class="ws-overlay chat-tool-popup" :data-theme="theme"><header><strong>Tools for this chat</strong><InfoHint :theme="theme" label="About connected tools">Connect a data source and choose which read-only tools this conversation can use.</InfoHint><button @click="load" aria-label="Refresh tools"><RefreshCw :size="15" /></button></header><p v-if="error" role="alert">{{ error }}</p><p v-else-if="!tools.length">No tools selected yet.</p><template v-else><input v-model="query" type="search" aria-label="Search connected tools" placeholder="Search tools…" /><div class="chat-tools-list"><label v-for="tool in filtered" :key="tool.id"><input type="checkbox" :checked="selected.includes(tool.id)" @change="toggle(tool.id)" /><span><b>{{ tool.name }}</b><small>{{ tool.connector }}</small></span></label></div></template><button class="chat-tools-configure" @click="open=false;emit('configure')"><Plug :size="15" />Manage connections</button></PopoverContent></Popover></template>
<script setup>
import { computed, ref, watch } from 'vue'
import InfoHint from './InfoHint.vue'
import { Wrench, RefreshCw, Plug } from 'lucide-vue-next'
import { Popover, PopoverContent, PopoverTrigger } from '../ui/popover'
import { api } from '../../workspace/api'
const props=defineProps({modelValue:{default:null},disabled:Boolean,theme:{default:'light'}})
const emit=defineEmits(['update:modelValue','configure'])
const open=ref(false),tools=ref([]),query=ref(''),error=ref('')
const selected=computed(()=>props.modelValue===null?tools.value.map(t=>t.id):props.modelValue)
const filtered=computed(()=>tools.value.filter(t=>`${t.name} ${t.connector}`.toLowerCase().includes(query.value.toLowerCase())))
async function load(){error.value='';try{const rows=await api('/api/workspace/connectors');tools.value=rows.filter(c=>c.enabled).flatMap(c=>(c.tools||[]).filter(t=>t.read_only&&c.allowed_tools.includes(t.name)).map(t=>({id:`${c.id}/${t.name}`,name:t.name.replaceAll('_',' '),connector:c.name})))}catch(e){error.value=e.message}}
function toggle(id){const next=new Set(selected.value);next.has(id)?next.delete(id):next.add(id);emit('update:modelValue',[...next])}
watch(open,value=>{if(value)load()})
</script>
<style scoped>
.chat-tools-trigger{display:inline-flex;align-items:center;gap:6px;border:0;background:transparent;color:var(--muted);font-size:12px;cursor:pointer;padding:7px!important;white-space:nowrap}:global(.chat-tool-popup){width:min(360px,calc(100vw - 24px));padding:16px!important;max-height:min(460px,70dvh);overflow:auto;border-radius:16px!important}.chat-tool-popup header{display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:14px;margin-bottom:12px}.chat-tool-popup header button{border:0;background:transparent;cursor:pointer}.chat-tool-popup>input{padding:9px 10px;width:100%;border:1px solid var(--line);border-radius:8px;font-size:13px}.chat-tool-popup p{font-size:13px;line-height:1.6;color:var(--muted)}.chat-tools-list{max-height:280px;overflow:auto;margin:8px 0}.chat-tools-list label{display:flex;align-items:center;gap:10px;padding:10px 4px;cursor:pointer}.chat-tools-list input{accent-color:var(--accent);width:16px;height:16px}.chat-tools-list b{font-size:13px;font-weight:500}.chat-tools-list small{display:block;font-size:11px;color:var(--muted);margin-top:3px}.chat-tools-configure{display:flex;align-items:center;gap:8px;width:100%;border:1px solid var(--line);background:var(--panel-2);border-radius:9px;padding:10px 12px;cursor:pointer;font-size:13px;margin-top:12px}

:global(.ws .direct-chat .direct-composer-options>button.chat-tools-trigger){height:30px;min-height:30px;padding:6px 8px!important;gap:6px;border-radius:8px;font-size:12px;line-height:18px;font-weight:400}
:global(.ws .direct-chat .direct-composer-options>button.chat-tools-trigger>svg){width:14px;height:14px;flex-shrink:0}
:global(.ws .direct-chat .direct-composer-options>button.chat-tools-trigger:hover){background:var(--panel-2);color:var(--text)}
:global(.ws .direct-chat .direct-composer-options>button.chat-tools-trigger:focus-visible){outline:2px solid var(--accent);outline-offset:2px}
:global(.ws .direct-chat .direct-composer-options>button.chat-tools-trigger:disabled){opacity:.5;cursor:default}
.chat-tool-popup header{font-size:13px;line-height:20px;gap:9px}.chat-tool-popup header>button{display:grid;place-items:center;width:28px;height:28px;border-radius:7px;flex-shrink:0;color:var(--muted)}.chat-tool-popup header>button:hover{background:var(--panel-2)}.chat-tool-popup input[type=search]{height:36px;padding:7px 10px;font-size:13px;line-height:20px}.chat-tools-list label{padding:9px 6px;border-radius:7px}.chat-tools-list label:hover{background:var(--panel-2)}.chat-tools-list b{font-size:13px;line-height:20px}.chat-tools-list small{font-size:12px;line-height:18px;margin-top:1px}.chat-tool-popup .chat-tools-configure{min-height:36px;padding:8px 10px;gap:8px;font-size:12px;line-height:18px}.chat-tool-popup .chat-tools-configure>svg{width:14px;height:14px}.chat-tool-popup :focus-visible{outline:2px solid var(--accent);outline-offset:2px}
</style>
